INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist COBOL heute völlig veraltet?', 2, '[{"text": "Nein", "correct": true, "because": "Wird in Banken noch genutzt"}, {"text": "Ja", "correct": false, "because": "Legacy-Systeme halten es alive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht die Sprache besonders?', 3, '[{"text": "Lesbarkeit", "correct": true, "because": "Englisch-ähnliche Syntax"}, {"text": "Objektorientierung", "correct": false, "because": "Späte Ergänzung"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche nutzen diese Programmiersprache oft?', 4, '[{"text": "Finanzwesen", "correct": true, "because": "Verlässlich für Transaktionen"}, {"text": "Mainframe-Systeme", "correct": true, "because": "Historische Stärke"}, {"text": "Webentwicklung", "correct": false, "because": "Falscher Einsatzbereich"}, {"text": "Gaming", "correct": false, "because": "Nicht geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) COBOL ist für Datenverarbeitung optimiert. b) Es unterstützt keine modernen IDEs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Moderne Tools existieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich mit dieser Sprache arbeite?', 4, '[{"text": "Datenstrukturen", "correct": false, "because": "Kern der Sprache"}, {"text": "Transaktionssicherheit", "correct": false, "because": "Wichtig für Einsatz"}, {"text": "Grafische Oberflächen", "correct": true, "because": "Nicht ihr Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Sprache Schleifen unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "PERFORM ist dafür da"}, {"text": "Nein", "correct": false, "because": "Grundfunktion enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur nutze ich für eine einfache Bedingung?', 3, '[{"text": "IF-Anweisung", "correct": true, "because": "Klassische Logik"}, {"text": "GOTO", "correct": false, "because": "Nur für Sprung"}, {"text": "CALL", "correct": false, "because": "Unterprogramme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen die Sprache robust?', 5, '[{"text": "Stabile Datenverarbeitung", "correct": true, "because": "Für große Volumen"}, {"text": "Fehlerbehandlung", "correct": true, "because": "Verlässlich bei Ausnahmen"}, {"text": "Hohe Portabilität", "correct": false, "because": "Mainframe-gebunden"}, {"text": "Multithreading", "correct": false, "because": "Nicht nativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) COBOL ist für Großrechner. b) Es ist schneller als Java. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein typisches Projekt damit?', 4, '[{"text": "Datenbankzugriff", "correct": false, "because": "Häufig genutzt"}, {"text": "Dateiverwaltung", "correct": false, "because": "Kernfunktion"}, {"text": "3D-Grafik", "correct": true, "because": "Außerhalb des Anwendungsbereichs"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird die Sprache nur im Batch-Modus genutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interaktiv möglich"}, {"text": "Ja", "correct": false, "because": "Flexibler Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet sie für Legacy-Systeme?', 4, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Langjährig bewährt"}, {"text": "Datenverarbeitung", "correct": true, "because": "Optimiert für große Mengen"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Eher wartungsstark"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass sie keine Variablen unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "DATA DIVISION definiert sie"}, {"text": "Ja", "correct": false, "because": "Grundfunktion enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Programm damit?', 3, '[{"text": "Klarheit der Struktur", "correct": true, "because": "Lesbarkeit ist Stärke"}, {"text": "Maximale Performance", "correct": false, "because": "Nicht der Fokus"}, {"text": "Kürzester Code", "correct": false, "because": "Eher ausführlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie ist für Geschäftssysteme. b) Sie ist plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mainframe-orientiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben löst sie effektiv?', 5, '[{"text": "Lohnabrechnung", "correct": true, "because": "Datenintensiv"}, {"text": "Transaktionsverarbeitung", "correct": true, "because": "Bankenstärke"}, {"text": "Machine Learning", "correct": false, "because": "Falscher Bereich"}, {"text": "Animation", "correct": false, "because": "Nicht geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Arbeit damit unwichtig?', 3, '[{"text": "Dateioperationen", "correct": false, "because": "Kernfunktion"}, {"text": "Datenintegrität", "correct": false, "because": "Wichtig für Zuverlässigkeit"}, {"text": "Responsive Design", "correct": true, "because": "Nicht ihr Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt sie moderne Datenbanken?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Erweiterungen möglich"}, {"text": "Nein", "correct": false, "because": "Anpassungen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob sie für kleine Projekte geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Für große Systeme optimiert"}, {"text": "Ja", "correct": false, "because": "Zu schwerfällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept steht im Mittelpunkt?', 4, '[{"text": "Datenverarbeitung", "correct": true, "because": "Historischer Zweck"}, {"text": "Event-Driven Design", "correct": false, "because": "Nicht ihr Ansatz"}, {"text": "Microservices", "correct": false, "because": "Moderne Architektur"}]');
